from functools import cmp_to_key


def _parse(v):
    v_main = v.split('+', 1)[0]
    if '-' in v_main:
        core, pre = v_main.split('-', 1)
    else:
        core, pre = v_main, None
    major, minor, patch = (int(x) for x in core.split('.'))
    return (major, minor, patch), pre


def _compare_pre(a, b):
    for ia, ib in zip(a, b):
        a_num = ia.isdigit()
        b_num = ib.isdigit()
        if a_num and b_num:
            na, nb = int(ia), int(ib)
            if na != nb:
                return -1 if na < nb else 1
        elif a_num and not b_num:
            return -1
        elif not a_num and b_num:
            return 1
        else:
            if ia != ib:
                return -1 if ia < ib else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _compare(v1, v2):
    core1, pre1 = _parse(v1)
    core2, pre2 = _parse(v2)
    if core1 != core2:
        return -1 if core1 < core2 else 1
    if pre1 is None and pre2 is None:
        return 0
    if pre1 is None:
        return 1
    if pre2 is None:
        return -1
    return _compare_pre(pre1.split('.'), pre2.split('.'))


def semver_sort(versions):
    return sorted(versions, key=cmp_to_key(_compare))

